import 'dart:io';
import 'dart:ui' as ui;

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:nothingness/debug_hooks.dart';
import 'package:nothingness/models/cassette_screen_config.dart';
import 'package:nothingness/models/operating_mode.dart';
import 'package:nothingness/models/screen_config.dart';
import 'package:nothingness/models/theme_id.dart';
import 'package:nothingness/services/settings_service.dart';
import 'package:nothingness/theme/themes.dart';
import 'package:nothingness/widgets/void_settings_sheet.dart';

/// Captures a screenshot of the Void Settings sheet with Cassette selected.
///
/// Output path: .tmp/cassette_settings_region.png
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  testWidgets('captures screenshot with Cassette selected', (tester) async {
    final settings = SettingsService();
    settings.operatingModeNotifier.value = OperatingMode.own;
    settings.screenConfigNotifier.value = const CassetteScreenConfig(
      variant: CassetteVariant.v3,
    );

    // Give the ListView enough height so the relevant rows are realised.
    await tester.binding.setSurfaceSize(const Size(420, 900));

    final app = MaterialApp(
      theme: buildAppTheme(id: ThemeId.void_, brightness: Brightness.dark),
      home: const VoidSettingsSheet(),
    );

    // Wrap with the same screenshot boundary used by the debug harness.
    await tester.pumpWidget(
      RepaintBoundary(
        key: DebugHooks.screenshotBoundaryKey,
        child: app,
      ),
    );
    await tester.pumpAndSettle();

    final boundaryFinder = find.byKey(DebugHooks.screenshotBoundaryKey);
    expect(boundaryFinder, findsOneWidget);

    final boundary = tester.renderObject<RenderRepaintBoundary>(
      boundaryFinder,
    );

    final image = await boundary.toImage(pixelRatio: 1);
    final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
    expect(byteData, isNotNull);

    final bytes = byteData!.buffer.asUint8List();
    final outPath = '.tmp/cassette_settings_region.png';
    await File(outPath).writeAsBytes(bytes, flush: true);

    expect(File(outPath).existsSync(), isTrue);
  });
}

